# -*- coding: utf-8 -*-
from odoo import models, fields, api

class AccountAssetAsset(models.Model):
    _name = 'account.asset.asset'
    _description = 'ACCOUNT ASSET ASSET'
    _order = 'id desc'

    activity_ids = fields.One2many(comodel_name="mail.activity", inverse_name='parent_id', string="Activities")
    activity_state = fields.Selection(selection=[["overdue","Overdue"],["today","Today"],["planned","Planned"]], string="Activity State", readonly=True, help="Status based on activities\nOverdue: Due date is already passed\nToday: Activity date is today\nPlanned: Future activities.")
    activity_user_id = fields.Many2one(comodel_name="res.users", string="Responsible User")
    activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Next Activity Type")
    activity_type_icon = fields.Char(string="Activity Type Icon", readonly=True, help="Font awesome icon e.g. fa-tasks")
    activity_date_deadline = fields.Date(string="Next Activity Deadline", readonly=True)
    my_activity_date_deadline = fields.Date(string="My Activity Deadline", readonly=True)
    activity_summary = fields.Char(string="Next Activity Summary")
    activity_exception_decoration = fields.Selection(selection=[["warning","Alert"],["danger","Error"]], string="Activity Exception Decoration", readonly=True, help="Type of the exception activity on record.")
    activity_exception_icon = fields.Char(string="Icon", readonly=True, help="Icon to indicate an exception activity.")
    activity_calendar_event_id = fields.Many2one(comodel_name="calendar.event", string="Next Activity Calendar Event", readonly=True)
    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", inverse_name='parent_id', string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment")
    website_message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Website Messages", help="Website communication history")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    entry_count = fields.Integer(string="# Asset Entries", readonly=True)
    posted_entry_count = fields.Integer(string="Posted Entry Count", readonly=True, help="A technical field to show/hide Set to Draft button.")
    name = fields.Char(string="Asset Name", required=True, readonly=True)
    code = fields.Char(string="Reference", readonly=True)
    value = fields.Float(string="Original Value", required=True, readonly=True)
    original_move_line_ids = fields.Many2many(comodel_name="account.move.line", string="Related Purchase Journal Items", help="The journal items related to purchases of this asset")
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", required=True, readonly=True)
    company_id = fields.Many2one(comodel_name="res.company", string="Company", required=True, readonly=True)
    note = fields.Text(string="Note")
    category_id = fields.Many2one(comodel_name="account.asset.category", string="Category", required=True, readonly=True)
    date = fields.Date(string="Date", required=True, readonly=True)
    state = fields.Selection(selection=[["draft","Draft"],["open","Running"],["close","Close"],["stock_in","Stock-In"],["sold","Sold"],["disposed","Disposed"]], string="Status", required=True, help="When an asset is created, the status is 'Draft'.\nWhen an asset is confirmed, the status is 'Running'. The depreciation lines is created and can be posted in the accounting.\nWhen an asset is sold, the status is 'Sold'. When an asset is disposed, the status is 'Disposed'\nYou can manually close an asset when the depreciation is over. If the last line of depreciation is posted, the asset automatically goes in that status.")
    active = fields.Boolean(string="Active")
    partner_id = fields.Many2one(comodel_name="res.partner", string="Partner", readonly=True)
    partner_user_id = fields.Many2one(comodel_name="res.partner", string="User")
    depreciation_expense_account_id = fields.Many2one(comodel_name="account.account", string="Expense Account", readonly=True, help="Account used in the periodical entries, to record a part of the asset as expense.When no account is set here, the Depreciation Entries: Expense Account on Asset Category will be used instead.")
    revaluation_decrease_account_id = fields.Many2one(comodel_name="account.account", string="Decrease Asset Account", readonly=True, help="Account used in the revaluation entries, to revaluation decrease a part of the asset. When no account is set here, the Revaluation Entries: Decrease Asset Account on Asset Category will be used instead.")
    revaluation_increase_account_id = fields.Many2one(comodel_name="account.account", string="Increase Asset Account", readonly=True, help="Account used in the revaluation entries, to revaluation increase a part of the asset. When no account is set here, the Revaluation Entries: Increase Asset Account on Asset Category will be used instead.")
    method = fields.Selection(selection=[["linear","Linear"],["degressive","Degressive"],["degressive_then_linear","Accelerated Degressive"]], string="Computation Method", required=True, readonly=True, help="The method that is used to compute the amount of depreciation lines.\n  * Linear = Original Value / Number of Depreciations\n  * Degressive = Residual Value * Degressive Factor\n  * Accelerated Degressive: Like Degressive but to keep minimum depreciation value equal to Linear value\n")
    method_number = fields.Integer(string="Number of Depreciations", readonly=True, help="Please enter the number of depreciations that is needed to depreciate your asset")
    method_period = fields.Integer(string="Number of Months in a Period", required=True, readonly=True, help="Choose the time between 2 depreciations here, in months")
    method_end = fields.Date(string="Ending Date", readonly=True)
    method_progress_factor = fields.Float(string="Degressive Factor", readonly=True)
    value_residual = fields.Float(string="Residual Value", readonly=True)
    method_time = fields.Selection(selection=[["number","Number of Entries"],["end","Ending Date"]], string="Time Method", required=True, readonly=True, help="Choose the method to use to compute the dates and number of entries.\n  * Number of Entries: Fix the number of entries and the time between 2 depreciations.\n  * Ending Date: Choose the time between 2 depreciations and the date the depreciations won't go beyond.")
    prorata = fields.Boolean(string="Prorata Temporis", readonly=True, help="Indicates that the first depreciation entry for this asset have to be done from the asset date instead of the first January / Start date of fiscal year")
    depreciation_line_ids = fields.One2many(comodel_name="account.asset.depreciation.line", inverse_name='parent_id', string="Depreciation Lines", readonly=True)
    revaluation_line_ids = fields.One2many(comodel_name="account.asset.revaluation.line", inverse_name='parent_id', string="Revaluation Asset", readonly=True)
    depreciation_progress = fields.Float(string="Depreciation Progress", readonly=True)
    salvage_value = fields.Float(string="Non-Depreciated Value", readonly=True, help="It is the amount you plan to have that you cannot depreciate.")
    revaluation_value = fields.Float(string="Revaluation Value", readonly=True, help="It is the amount you plan to have that you cannot depreciate.")
    invoice_line_id = fields.Many2one(comodel_name="account.move.line", string="Invoice Line", readonly=True)
    invoice_id = fields.Many2one(comodel_name="account.move", string="Invoice", readonly=True)
    move_ids = fields.One2many(comodel_name="account.move", inverse_name='parent_id', string="Journal Entries", readonly=True, help="This technical field that stores all the journal disposal entries, journal sell entries")
    type = fields.Selection(selection=[["sale","Sale: Revenue Recognition"],["purchase","Purchase: Asset"]], string="Type", required=True)
    product_id = fields.Many2one(comodel_name="product.product", string="Asset Product", readonly=True, help="The product that presents the asset")
    date_first_depreciation = fields.Selection(selection=[["last_day_period","Based on Last Day of Month"],["manual","Manual"]], string="Depreciation Dates", required=True, readonly=True, help="The way to compute the date of the first depreciation.\n  * Based on last day of month: The depreciation dates will be based on the last day of the month.\n  * Manual: You will need set manually depreciation dates.")
    first_depreciation_date = fields.Date(string="First Depreciation Date", readonly=True, help="It simply changes its accounting date. This date does not alter the computation of the first journal entry in case of prorata temporis assets.")
    asset_type = fields.Selection(selection=[["asset","Fixed Asset"],["tools","Instrument and tools"]], string="Asset Type", readonly=True)
